    try:
        txt=p.read_text(encoding='utf-8', errors='ignore')
    except Exception: continue
    low=txt.lower()
    if any(k in low for k in ['send_voice','reply_voice','text_to_speech','tts','voice_mode','voice reply','audio/ogg','opus','ogg']):
        print('\n###', p.relative_to(root))
